  final LibraryController? libraryController;

  @override
  Widget build(BuildContext context) {
    final settingsService = useMemoized(() => SettingsService());

    // B-015: lets the crumb's jump tap drive scrollToTrack after loadFolder.
    final browserController = useMemoized(() => VoidBrowserController());
    useEffect(() => browserController.dispose, [browserController]);

    // Whether a now-playing row is currently outside the browser viewport.
    final playingTrackOutsideVisibleRegion =
        useListenable(browserController.playingTrackOutsideVisibleRegion);

